(3206739, 450562, 71330, '<td valign="top">ok</td>', 'ok', '2007-01-10 14:04:37.000000', NULL, 1),
(3206740, 449857, 12200, '<td valign="top">Very flattering, but for my artistic taste (entirely subjective), this feels too "posed" and hence "unnatural" for me. The subject''s expression is nice...though distant.</td>', 'Very flattering, but for my artistic taste (entirely subjective), this feels too "posed" and hence "unnatural" for me. The subject''s expression is nice...though distant.', '2007-01-10 14:04:53.000000', NULL, 1),
