INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(3209090, 449629, 12200, '<td valign="top">Sorry, but this perspective just doesn''t work for me. I think I would have liked it far better with just the left panel.</td>', 'Sorry, but this perspective just doesn''t work for me. I think I would have liked it far better with just the left panel.', '2007-01-10 20:29:20.000000', NULL, 1),
(3209094, 449985, 12200, '<td valign="top">Whoa those are some bright highlights in her face. I would strongly suggest diffusing the glow on this shot to soften those fine details in her face, which are not very attractive at this proximity. Compositionally, I really like the cropping. 4 from me.</td>', 'Whoa those are some bright highlights in her face. I would strongly suggest diffusing the glow on this shot to soften those fine details in her face, which are not very attractive at this proximity. Compositionally, I really like the cropping. 4 from me.', '2007-01-10 20:30:24.000000', NULL, 1),
(3209098, 449985, 5436, '<td valign="top">Nice lighting in her eyes.</td>', 'Nice lighting in her eyes.', '2007-01-10 20:30:46.000000', NULL, 1),
(3209100, 448620, 62277, '<td valign="top">is that george hamilton? i wondered where he got to.</td>', 'is that george hamilton? i wondered where he got to.', '2007-01-10 20:30:49.000000', NULL, 1),
(3209104, 450863, 12200, '<td valign="top">Your post-processing her looks a bit over-compensatory, especially around the eyes, where it looks like an unsharp mask or noise tool was used a bit to liberally. Composition is otherwise quite strong.</td>', 'Your post-processing her looks a bit over-compensatory, especially around the eyes, where it looks like an unsharp mask or noise tool was used a bit to liberally. Composition is otherwise quite strong.', '2007-01-10 20:31:44.000000', NULL, 1),
(3209108, 448586, 31341, '<td valign="top">I''m usuually not partial to pet portraits, but this is very well done in my opinion.  Nice eye.</td>', 'I''m usuually not partial to pet portraits, but this is very well done in my opinion.  Nice eye.', '2007-01-10 20:32:14.000000', NULL, 1),
(3209118, 450467, 12200, '<td valign="top">Lovely shot with a beautiful subject. Would have been far better with some enhanced contrast and some creative editing to lighten that far wall.</td>', 'Lovely shot with a beautiful subject. Would have been far better with some enhanced contrast and some creative editing to lighten that far wall.', '2007-01-10 20:33:39.000000', NULL, 1),
(3209119, 448437, 31341, '<td valign="top">The focus is off, otherwise it has some potential.</td>', 'The focus is off, otherwise it has some potential.', '2007-01-10 20:33:41.000000', NULL, 1),
(3209123, 450822, 69387, '<td valign="top">Danger!</td>', 'Danger!', '2007-01-10 20:33:59.000000', NULL, 1),
(3209127, 449501, 12200, '<td valign="top">Very nice composition. Burn that left horse''s features and the reins to contrast it better against the light, and maybe blur that background with the vehicles, and I think you''d have an even stronger and more striking piece of work.</td>', 'Very nice composition. Burn that left horse''s features and the reins to contrast it better against the light, and maybe blur that background with the vehicles, and I think you''d have an even stronger and more striking piece of work.', '2007-01-10 20:34:50.000000', NULL, 1),
(3209128, 450496, 69387, '<td valign="top">Wow! incredible shot!</td>', 'Wow! incredible shot!', '2007-01-10 20:34:51.000000', NULL, 1),
(3209137, 450617, 12200, '<td valign="top">DNMC. No living subject, no portrait orientation...heck not even a title to try and persuade me.</td>', 'DNMC. No living subject, no portrait orientation...heck not even a title to try and persuade me.', '2007-01-10 20:37:04.000000', NULL, 1),
(3209144, 450472, 33161, '<td valign="top">This picture is horrible.</td>', 'This picture is horrible.', '2007-01-10 20:38:32.000000', NULL, 1),
(3209147, 449689, 62277, '<td valign="top">i little too blown out for my liking.. lose too many features</td>', 'i little too blown out for my liking.. lose too many features', '2007-01-10 20:39:06.000000', NULL, 1),
(3209148, 448933, 12200, '<td valign="top">Man...this is definitely one of my fav''s. It looks like something that should be on the book jacket of a novel, don''t you think?</td>', 'Man...this is definitely one of my fav''s. It looks like something that should be on the book jacket of a novel, don''t you think?', '2007-01-10 20:39:08.000000', NULL, 1),
