(3214913, 450545, 66602, '<td valign="top">like the composition and focus</td>', 'like the composition and focus', '2007-01-11 22:11:38.000000', NULL, 1),
(3214917, 449716, 66602, '<td valign="top">great use of the light reflected in the eyes</td>', 'great use of the light reflected in the eyes', '2007-01-11 22:12:14.000000', NULL, 1),
