(3221280, 450735, 63588, '<td valign="top">Love the eyes. I''d prefer it not quite so pale - baby gets a bit of an alien aura.</td>', 'Love the eyes. I''d prefer it not quite so pale - baby gets a bit of an alien aura.', '2007-01-12 17:29:22.000000', NULL, 1),
(3221282, 448568, 41746, '<td valign="top">I think this would be a killer image without the hose. It´s not working for me, sorry. I find the model attractive, beautiful eyes, perfect lighting. 6.</td>', 'I think this would be a killer image without the hose. It´s not working for me, sorry. I find the model attractive, beautiful eyes, perfect lighting. 6.', '2007-01-12 17:29:26.000000', NULL, 1),
(3221283, 449373, 33400, '<td valign="top">Very pretty. The soft focus works here, but I''d be interested to see her eyes a little sharper.</td>', 'Very pretty. The soft focus works here, but I''d be interested to see her eyes a little sharper.', '2007-01-12 17:29:35.000000', NULL, 1),
(3221287, 448287, 65234, '<td valign="top">The thing which draws my eye is her nostril ... doesn''t seem like a flattering portrait.</td>', 'The thing which draws my eye is her nostril ... doesn''t seem like a flattering portrait.', '2007-01-12 17:30:00.000000', NULL, 1),
(3221298, 448623, 65234, '<td valign="top">Softness works pretty well here.</td>', 'Softness works pretty well here.', '2007-01-12 17:31:43.000000', NULL, 1),
