(3226386, 450515, 62626, '<td valign="top">wow, this really grabbed my attention. Nice contrast between lights and darks.</td>', 'wow, this really grabbed my attention. Nice contrast between lights and darks.', '2007-01-13 15:51:57.000000', NULL, 1),
(3226389, 448939, 71239, '<td valign="top">Very creative shot, adds a lot of extra interest by including the camera.</td>', 'Very creative shot, adds a lot of extra interest by including the camera.', '2007-01-13 15:52:36.000000', NULL, 1),
