(3228273, 450842, 70828, '<td valign="top">VERY cute! Focus and tonal range right on the button I would crop it in on the left all the way to the lip of the cuff. - 9</td>', 'VERY cute! Focus and tonal range right on the button I would crop it in on the left all the way to the lip of the cuff. - 9', '2007-01-13 23:26:09.000000', NULL, 1),
(3228275, 449540, 70828, '<td valign="top">Magical ... 9</td>', 'Magical ... 9', '2007-01-13 23:26:20.000000', NULL, 1),
