(3228300, 449858, 70828, '<td valign="top">Spooky ... BINGO DOF. I like this a lot. 9</td>', 'Spooky ... BINGO DOF. I like this a lot. 9', '2007-01-13 23:30:39.000000', NULL, 1),
(3228301, 448569, 29513, '<td valign="top">IMHO, every bit of light value in the frame that is not the face, distracts from the face.  I know this is rather picky, but this is quite good.  I might try to get a bit more shadow on the left side of the face.</td>', 'IMHO, every bit of light value in the frame that is not the face, distracts from the face.  I know this is rather picky, but this is quite good.  I might try to get a bit more shadow on the left side of the face.', '2007-01-13 23:30:43.000000', NULL, 1),
