(3228501, 450523, 44754, '<td valign="top">Wish the camera was more in focus.</td>', 'Wish the camera was more in focus.', '2007-01-14 00:32:32.000000', NULL, 1),
(3228503, 447645, 29513, '<td valign="top">A dark background would really set off her hair and skin tones.</td>', 'A dark background would really set off her hair and skin tones.', '2007-01-14 00:33:04.000000', NULL, 1),
