(3229858, 449662, 66201, '<td valign="top">Coming back to this and changing my vote. I just really like this one a whole lot.</td>', 'Coming back to this and changing my vote. I just really like this one a whole lot.', '2007-01-14 12:02:41.000000', NULL, 1),
(3229861, 449875, 66201, '<td valign="top">Beautiful family portrait. Very precious.</td>', 'Beautiful family portrait. Very precious.', '2007-01-14 12:03:43.000000', NULL, 1),
(3229965, 449196, 30049, '<td valign="top">Appears to be a pretty young lady, but we can''t see her in this photo.  The scarf/hat is cute, but obstructing the view.  Could stand to apply some curves/levels adjustments to balance this out a little.  Seems underexposed and needing some additional contrast.  All JMO of course.  Good luck in the challenge.</td>', 'Appears to be a pretty young lady, but we can''t see her in this photo.  The scarf/hat is cute, but obstructing the view.  Could stand to apply some curves/levels adjustments to balance this out a little.  Seems underexposed and needing some additional contrast.  All JMO of course.  Good luck in the challenge.', '2007-01-14 12:38:26.000000', NULL, 1),
(3229992, 447482, 37390, '<td valign="top">I love the tonal range, and expression in this image. THe eyes look a little strange (but kinda cool) maybe a little over sharpened. Top left side of forhead looks to smooth doesn''t match the rest of his forehead. Great shot. Keep at it!</td>', 'I love the tonal range, and expression in this image. THe eyes look a little strange (but kinda cool) maybe a little over sharpened. Top left side of forhead looks to smooth doesn''t match the rest of his forehead. Great shot. Keep at it!', '2007-01-14 12:53:41.000000', NULL, 1),
(3229993, 450496, 56167, '<td valign="top">nice eyes</td>', 'nice eyes', '2007-01-14 12:54:16.000000', NULL, 1),
(3229999, 450674, 56167, '<td valign="top">nice boy, good detail</td>', 'nice boy, good detail', '2007-01-14 12:57:31.000000', NULL, 1),
